#include <vector>
#include <unordered_set>

using namespace std;

class Solution {
public:
    int maximalNetworkRank(int n, vector<vector<int>>& roads) {
        vector<int> deg(n, 0);
        unordered_set<int> connected[n];
        for (auto& r : roads) {
            deg[r[0]]++;
            deg[r[1]]++;
            connected[r[0]].insert(r[1]);
            connected[r[1]].insert(r[0]);
        }
        int res = 0;
        for (int i = 0; i < n; ++i)
            for (int j = i + 1; j < n; ++j) {
                int rank = deg[i] + deg[j] - (connected[i].count(j) ? 1 : 0);
                res = max(res, rank);
            }
        return res;
    }
};
